package com.ivonix.pulse.ontology.domain;
import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import java.util.*;
@Service public class IndustrialService extends DomainDataService { public IndustrialService(JdbcTemplate j){super(j,"industrial_data",Set.of("vibration_rms","temperature","current_draw","speed_rpm"));} public DomainDiagnosticResult diagnose(UUID d,UUID o){var x=latest(d,o,1);if(!x.isEmpty()){double v=number(x.get(0),"vibration_rms"),t=number(x.get(0),"temperature");if(!Double.isNaN(v)&&v>1.5)return new DomainDiagnosticResult("industrial","Bearing vibration anomaly",.85,List.of("Inspect bearing condition","Check alignment"));if(!Double.isNaN(t)&&t>85)return new DomainDiagnosticResult("industrial","Overheating",.92,List.of("Check cooling","Inspect thermal load"));}return new DomainDiagnosticResult("industrial","No immediate rule-based fault",.10,List.of("Continue monitoring"));}}